# ================================================================== S07: সারাংশ
class P2S07(BaseScene):
    T = 20.0

    def body(self):
        t = bn("পর্ব ২ শেষ!", 42, ACCENT, BOLD).move_to(UP * 2.4)
        self.p(FadeIn(t, scale=1.1), rt=0.8)
        items = VGroup(
            bn("✓ পল্লি-উপকথা ও রূপকথা", 22, INK),
            bn("✓ Folklore Society", 22, INK),
            bn("✓ প্রবাদ বাক্য ও খনার বচন", 22, INK),
        ).arrange(DOWN, buff=0.26, aligned_edge=LEFT).move_to(UP * 0.4)
        for i, tt in enumerate([2.6, 5.2, 7.8]):
            self.upto(tt)
            self.p(FadeIn(items[i], shift=UP * 0.1), rt=0.5)
        nxt = bn("পরের পর্বে: ছড়া · খেলাধুলা · পল্লিগান", 19, ACCENT2, MEDIUM)
        if nxt.width > 6.5:
            nxt.scale_to_fit_width(6.5)
        nb = RoundedRectangle(corner_radius=0.1, width=nxt.width + 0.6, height=nxt.height + 0.45,
                               fill_color=HL, fill_opacity=1, stroke_color=ACCENT2, stroke_width=1.5)
        g = VGroup(nb, nxt.move_to(nb)).move_to(DOWN * 1.6)
        self.upto(11.5)
        self.p(FadeIn(g, shift=UP * 0.15), rt=0.8)
        bye = bn("দেখা হবে পর্ব ৩-এ!", 19, MUTED).move_to(DOWN * 3.0)
        self.upto(15.5)
        self.p(FadeIn(bye), rt=0.6)
